INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66653404', 66653404, 'analyze_legacy', 'Kementerian Komunikasi dan Digital', 'central', 'Direktorat Jenderal Ekosistem Digital', 'Pengujian Panggilan Internasional dalam Rangka Monitoring Potensi Fraud dari Panggilan Masuk Internasional pada Penyelenggaraan Telekomunikasi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Pusat (Kota)', 1244976000, 'March 2026', 'APBN - PNBP (D)', 1, 1, '11500', 'Pekerjaan ini berfokus pada penyediaan layanan pengujian panggilan internasional untuk memantau dan mencegah tindak kecurangan (fraud) di jaringan telekomunikasi nasional. Sebagai wujud komitmen pemerintah melindungi masyarakat dari penipuan, penyedia jasa akan menjalankan simulasi panggilan masuk dari luar negeri secara rutin. Simulasi dilakukan melalui dua pendekatan: rute mitra global (wholesale) dan pengujian langsung (direct call) menggunakan nomor seluler luar negeri, khususnya Malaysia. Didukung sistem pemantauan handal, penyedia akan melacak dan menganalisis kesesuaian identitas penelepon (caller ID) guna mendeteksi praktik ilegal seperti penyalahgunaan SIMbox dan manipulasi SIP trunk. Temuan ini akan diolah menjadi laporan analitis dan daftar hitam (blacklist) nomor terindikasi fraud. Hal ini memungkinkan operator seluler di Indonesia untuk segera melakukan pemblokiran demi menjaga keamanan masyarakat luas.', 'Pihak pelaksana diwajibkan untuk berlangganan dengan mitra global atau menggunakan SIM card dari operator di luar wilayah Indonesia untuk melakukan panggilan telepon internasional. Menyediakan kartu seluler penyelenggara domestik untuk menerima panggilan pada perangkat receiver. Kartu seluler penyelenggara domestik yang menjadi target pengujian meliputi PT Telekomunikasi Selular, PT Indosat Tbk, dan PT XL Smart Sejahtera Tbk. - Harus memiliki perangkat lunak yang dapat terhubung ke global partner untuk membangkitkan panggilan. - Perangkat lunak harus mampu melakukan pengecekan pada setiap A# number panggilan yang masuk ke perangkat receiver. - Menghasilkan reporting atau pelaporan terhadap seluruh panggilan yang dibangkitkan dari luar wilayah Indonesia beserta hasil pemantauan caller ID yang diterima', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2911864);
